package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// UserService handles user-related business logic
type UserService struct {
	users  map[string]User
	mutex  sync.RWMutex
}

// NewUserService creates and returns a new UserService
func NewUserService() *UserService {
	return &UserService{
		users: make(map[string]User),
	}
}

// GetAllUsers returns all users
func (s *UserService) GetAllUsers() []User {
	s.mutex.RLock()
	defer s.mutex.RUnlock()

	var list []User
	for _, u := range s.users {
		list = append(list, u)
	}
	return list
}

// CreateUser creates a new user and adds it to the system
func (s *UserService) CreateUser(user User) (User, error) {
	s.mutex.Lock()
	defer s.mutex.Unlock()

	user.ID = uuid.New().String()
	s.users[user.ID] = user
	return user, nil
}

// GetUserByID retrieves a user by their ID
func (s *UserService) GetUserByID(id string) (User, bool) {
	s.mutex.RLock()
	defer s.mutex.RUnlock()

	user, ok := s.users[id]
	return user, ok
}

package api

import (
	"encoding/json"
	"net/http"

	"experiment/internal/service"
)

// UserHandlers handles HTTP requests related to users
type UserHandlers struct {
	service *service.UserService
}

// NewUserHandlers creates and returns new UserHandlers
func NewUserHandlers(s *service.UserService) *UserHandlers {
	return &UserHandlers{service: s}
}

// HandleUsers handles requests to /users
func (h *UserHandlers) HandleUsers(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
		case http.MethodGet:
			h.GetAllUsers(w, r)
		case http.MethodPost:
			h.CreateUser(w, r)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// GetAllUsers handles GET /users
func (h *UserHandlers) GetAllUsers(w http.ResponseWriter, r *http.Request) {
	users := h.service.GetAllUsers()
	json.NewEncoder(w).Encode(users)
}

// CreateUser handles POST /users
func (h *UserHandlers) CreateUser(w http.ResponseWriter, r *http.Request) {
	var user service.User
	if err := json.NewDecoder(r.Body).Decode(&user); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	createdUser, err := h.service.CreateUser(user)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(createdUser)
}

// HandleUserByID handles requests to /users/{id}
func (h *UserHandlers) HandleUserByID(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]

	switch r.Method {
		case http.MethodGet:
			h.GetUserByID(w, r, id)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// GetUserByID handles GET /users/{id}
func (h *UserHandlers) GetUserByID(w http.ResponseWriter, r *http.Request, id string) {
	user, ok := h.service.GetUserByID(id)
	if !ok {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(user)
}

package main

import (
	"log"
	"net/http"

	"experiment/internal/api"
	"experiment/internal/service"
)

func main() {
	// Initialize the service
	userService := service.NewUserService()

	// Initialize the API handlers with the service
	userHandlers := api.NewUserHandlers(userService)

	// Register HTTP handlers
	http.HandleFunc("/users", userHandlers.HandleUsers)
	http.HandleFunc("/users/", userHandlers.HandleUserByID)

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package service_test

import (
	"experiment/internal/service"
	"testing"
)

func TestUserService(t *testing.T) {
	svc := service.NewUserService()

	// Test CreateUser
	user1 := service.User{Name: "Alice", Email: "alice@example.com"}
	createdUser1, err := svc.CreateUser(user1)
	if err != nil {
		t.Fatalf("CreateUser failed: %v", err)
	}
	if createdUser1.ID == "" {
		t.Error("Expected User ID to be generated, got empty")
	}

	// Test GetUserByID
	fetchedUser, ok := svc.GetUserByID(createdUser1.ID)
	if !ok {
		t.Fatalf("GetUserByID failed to find user with ID %s", createdUser1.ID)
	}
	if fetchedUser.Name != user1.Name || fetchedUser.Email != user1.Email {
		t.Errorf("Fetched user mismatch. Expected %+v, got %+v", user1, fetchedUser)
	}

	// Test GetAllUsers
	allUsers := svc.GetAllUsers()
	if len(allUsers) != 1 {
		t.Errorf("Expected 1 user, got %d", len(allUsers))
	}

	user2 := service.User{Name: "Bob", Email: "bob@example.com"}
	createdUser2, err := svc.CreateUser(user2)
	if err != nil {
		t.Fatalf("CreateUser failed: %v", err)
	}

	allUsers = svc.GetAllUsers()
	if len(allUsers) != 2 {
		t.Errorf("Expected 2 users, got %d", len(allUsers))
	}

	_, ok = svc.GetUserByID("nonexistent-id")
	if ok {
		t.Error("Expected GetUserByID to not find a nonexistent user")
	}
}
